Tool response:
Tool: create_payment
Description: Create Payment
Parameters:
    {
      "type": "object",
      "properties": {
        "invoice_id": {
          "type": "integer",
          "title": "Invoice Id"
        },
        "patient_id": {
          "type": "integer",
          "title": "Patient Id"
        },
        "amount": {
          "type": "number",
          "title": "Amount"
        },
        "payment_method": {
          "type": "string",
          "pattern": "^(cash|credit_card|debit_card|check|bank_transfer|insurance|other)$",
          "title": "Payment Method"
        },
        "reference_number": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Reference Number"
        },
        "notes": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "title": "Notes"
        }
      },
      "required": [
        "invoice_id",
        "patient_id",
        "amount",
        "payment_method"
      ]
    }

